const response = $input.first().json;
let loans = Array.isArray(response) ? response : (response.loans || []);

if (loans.length === 0) {
  console.log('[LendLoop] No overdue loans found for today.');
  return [];
}

const todayStr = new Date().toISOString().slice(0, 10);

return loans.map((loan) => {
  const dueDateStr = new Date(loan.dueDate).toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric'
  });

  return {
    json: {
      loanId: loan.loanId,
      toolTitle: loan.toolTitle,
      toolCategory: loan.toolCategory,
      borrowerName: loan.borrowerName,
      borrowerEmail: loan.borrowerEmail,
      dueDateStr,
      daysOverdue: loan.daysOverdue,
      reminderCount: loan.reminderCount || 0,
      // Idempotency key scoped to loan ID and calendar day to guarantee exactly-once reminder per day
      idempotencyKey: `reminder_${loan.loanId}_${todayStr}`,
      reminderMessage: `Hi ${loan.borrowerName}! Friendly neighborhood reminder from LendLoop: "${loan.toolTitle}" was due back on ${dueDateStr} (${loan.daysOverdue} days overdue). Please arrange return with the lender or request an extension.`
    }
  };
});

const item = $input.first().json;

// Mock notification dispatcher (can be swapped with SendGrid, SES, Resend, or Discord/Slack)
console.log(`[LendLoop Overdue Notification Dispatch] TO: ${item.borrowerEmail} (${item.borrowerName})`);
console.log(`SUBJECT: LendLoop Reminder: Overdue return of "${item.toolTitle}"`);
console.log(`BODY: ${item.reminderMessage}`);

return [{
  json: {
    ...item,
    dispatchedAt: Date.now(),
    deliveryStatus: 'delivered'
  }
}];

const crypto = require('crypto');
const item = $input.first().json;
const secret = $env.N8N_WEBHOOK_SECRET || 'lendloop_n8n_hmac_secret_dev';

const timestamp = Date.now().toString();
const payload = {
  loanId: item.loanId,
  idempotencyKey: item.idempotencyKey,
  deliveredVia: 'email'
};

const rawBody = JSON.stringify(payload);
const payloadToSign = `${timestamp}.${rawBody}`;
const signature = crypto.createHmac('sha256', secret).update(payloadToSign).digest('hex');

return [{
  json: {
    loanId: item.loanId,
    idempotencyKey: item.idempotencyKey,
    deliveredVia: 'email',
    signature,
    timestamp,
    rawBody
  }
}];
